        public void InitRenderer()
        {

            Debug.debugWindow.AddEntry("InitRenderer", "Initing renderer");

            glControl = new GLControl(new OpenTK.Graphics.GraphicsMode(32, 24, 8, 1));
            glControl.MakeCurrent();
            this.Controls.Add(glControl);
            glControl.Parent = this;
            glControl.Dock = DockStyle.Fill;
            glControl.Resize += glControl_Resize;
            glControl.Paint += glControl_Paint;
            //glControl.PreviewKeyDown += levelViewPanel_PreviewKeyDown;
            glControl.KeyDown += glControl_KeyDown;
            glControl.KeyUp += glControl_KeyUp;
            glControl.LostFocus += glControl_LostFocus;
            glControl.MouseDown += glControl_MouseClick;
            glControl.MouseMove += glControl_MouseMove;
            glControl.MouseUp += glControl_MouseUp;
            glControl.MouseWheel += glControl_MouseWheel;


            GL.Viewport(0, 0, this.Width, this.Height);
            camera = new Camera(3f, new Vector3(0, 0, 0), 90f, (float)this.Width / (float)this.Height, (float)Math.PI / 4.0f, (float)Math.PI / 6.0f);

            string shaderpath = "Rendering/Shaders/StaticGeometry/";
            shader = new Shader(shaderpath + "shader.vert", shaderpath + "shader.frag");
            solidColorShader = new Shader(shaderpath + "halo.vert", shaderpath + "halo.frag");
            selectionShader = new Shader(shaderpath + "selection.vert", shaderpath + "selection.frag");


            shaderpath = "Rendering/Shaders/PostProcessing/";
            edgeDetectionPPShader = new Shader(shaderpath + "edgeDetection.vert", shaderpath + "edgeDetection.frag");
            //GL.Enable(EnableCap.Blend);

            //GL.BlendFunc(BlendingFactor.SrcAlpha, BlendingFactor.OneMinusSrcAlpha);

            // Buffer used for handling selection with mouse pointer

            selectionFrame = new Frame(this.Width, this.Height);
            outlineFrame = new Frame(this.Width, this.Height);


            CreateDefaultTexture();

            // Render Stuff
            GL.ClearColor(backgroundColor);
            //GL.Enable();
            GL.Enable(EnableCap.CullFace);
            GL.Enable(EnableCap.Multisample);
            GL.Enable(EnableCap.DepthTest);
            GL.Enable(EnableCap.StencilTest);

            renderhelper = new(glControl);

            drawTimer = new();

            StartRenderLoop();
        }

        public void StartRenderLoop()
        {
            drawTimer.Interval = 1000 / TargetFps;
            drawTimer.Tick += (object sender, EventArgs e) => glControl.Invalidate();
            drawTimer.Start();
            //glControl.Invalidate();
        }

        

        public void CreateDefaultTexture()
        {
            defaultTexture = new GenericBuffer();
            defaultTexture.handle = GL.GenTexture();
            defaultTexture.hasHandle = true;

            GL.BindTexture(TextureTarget.Texture2D, defaultTexture.handle);

            // Code copied from the Texture importer
            Bitmap loadingmap = new Bitmap(Image.FromFile("Rendering/defaultTexture.png"));
            System.Drawing.Imaging.BitmapData loadingmapdata = loadingmap.LockBits(new Rectangle(0, 0, loadingmap.Width, loadingmap.Height), System.Drawing.Imaging.ImageLockMode.ReadOnly, System.Drawing.Imaging.PixelFormat.Format32bppArgb);


            GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureMinFilter, (int)TextureMinFilter.NearestMipmapNearest);
            GL.TexParameter(TextureTarget.Texture2D, TextureParameterName.TextureMagFilter, (int)TextureMagFilter.Nearest);
            GL.TexImage2D(TextureTarget.Texture2D, 0, PixelInternalFormat.Rgba, loadingmap.Width, loadingmap.Height,
                0, OpenTK.Graphics.OpenGL4.PixelFormat.Bgra, PixelType.UnsignedByte, loadingmapdata.Scan0);
            GL.GenerateMipmap(GenerateMipmapTarget.Texture2D);
        }

        


