        private void SetLightKitUniforms() // Make more general! Or set up system for seperated rendering. This isn't very nice!
        {



            List<TOCEntry> lightkits = resourcePool.lightKitPool;

            if (lightkits.Count > 10) { Debug.debugWindow.AddEntry("SetLightKitUniforms", "Warning: More than 10 lightkits"); return; }

            List<ulong> lookupIDs = new();
            foreach (TOCEntry entry in lightkits)
            {
                lookupIDs.Add(((SB09WiiAsset.LightKit)entry.entity).lookupTex);
            }

            List<BaseClass> lookupTextures = resourcePool.GetAssetsFromPool(resourcePool.aTexturePool, lookupIDs);


            int[] samplers = new int[10];
            for (int i = 0; i < lightkits.Count; i++)
            {
                if (lookupTextures[i] == null) continue;
                TextureBase tex = (TextureBase)lookupTextures[i];
                GL.ActiveTexture(TextureUnit.Texture6 + i);
                GL.BindTexture(TextureTarget.Texture2D, tex.buffer.handle);

                samplers[i] = 6 + i;

            }

            shader.SetInts("lightkitLookups", samplers);

            for (int i = 0; i < lightkits.Count; i++)
            {

                SB09WiiAsset.LightKit kit = (SB09WiiAsset.LightKit)lightkits[i].entity;

                shader.SetVector3($"lightkits[{i}].light1", VectorMath.DirectionFromYawPitchRoll(kit.dir.element0.orientation.GetVector3()));
                shader.SetVector3($"lightkits[{i}].light2", VectorMath.DirectionFromYawPitchRoll(kit.dir.element1.orientation.GetVector3()));
                shader.SetVector3($"lightkits[{i}].light3", VectorMath.DirectionFromYawPitchRoll(kit.dir.element2.orientation.GetVector3()));
                shader.SetVector3($"lightkits[{i}].light4", VectorMath.DirectionFromYawPitchRoll(kit.dir.element3.orientation.GetVector3()));

                FloatColorRGB vec = kit.dir.element2.color;
                shader.SetVector3($"lightkits[{i}].color3", new System.Numerics.Vector3(vec.r, vec.g, vec.b));
                vec = kit.dir.element3.color;
                shader.SetVector3($"lightkits[{i}].color4", new System.Numerics.Vector3(vec.r, vec.g, vec.b));

                vec = kit.ambientColor;
                shader.SetVector3($"lightkits[{i}].ambientcolor", new System.Numerics.Vector3(vec.r, vec.g, vec.b));
            }
        }

        private void SetupTextures(GeometryBase renderthis)
        {
            GL.ActiveTexture(TextureUnit.Texture0);
            if (renderthis.textureSet.diffuseMap.hasHandle) { GL.BindTexture(TextureTarget.Texture2D, renderthis.textureSet.diffuseMap.handle); }
            else { GL.BindTexture(TextureTarget.Texture2D, defaultTexture.handle); }

            GL.ActiveTexture(TextureUnit.Texture1);
            if (renderthis.textureSet.lightMap.hasHandle)
            {
                GL.BindTexture(TextureTarget.Texture2D, renderthis.textureSet.lightMap.handle);
            }

            GL.ActiveTexture(TextureUnit.Texture2);
            if (renderthis.textureSet.environmentMap.hasHandle)
            {
                GL.BindTexture(TextureTarget.Texture2D, renderthis.textureSet.environmentMap.handle);
            }
            GL.ActiveTexture(TextureUnit.Texture3);
            if (renderthis.textureSet.diffuseMap1.hasHandle)
            {
                GL.BindTexture(TextureTarget.Texture2D, renderthis.textureSet.diffuseMap1.handle);
            }
            GL.ActiveTexture(TextureUnit.Texture4);
            if (renderthis.textureSet.blendMap.hasHandle)
            {
                GL.BindTexture(TextureTarget.Texture2D, renderthis.textureSet.blendMap.handle);
            }
        }

        private void SetupFogUniforms()
        {
            if (resourcePool.fogPool.Count() <= 0)
            {
                shader.SetInt("fog.fogMode", 0);
                return;
            }
            SB09WiiAsset.Fog fog = (SB09WiiAsset.Fog)resourcePool.fogPool[0].entity;

            shader.SetFloat("fog.start", fog.start);
            shader.SetFloat("fog.end", fog.end);
            shader.SetInt("fog.fogMode", renderFog ? (int)fog.mode : 0);
            shader.SetColor4("fog.fogColor", new Color4(fog.color.r, fog.color.g, fog.color.b, fog.color.a));
        }

        private void DrawGeometryPool()
        {
            shader.Use();

            shader.SetMatrix4("project", camera.GetProjectionMatrix());
            shader.SetMatrix4("view", camera.GetViewMatrix());// Matrix4.LookAt(new Vector3(0, 3, 0), Vector3.Zero, new Vector3(0,0,1)));//camera.GetViewMatrix());
            shader.SetInt("diffuseMap", 0);
            shader.SetInt("lightMap", 1);
            shader.SetInt("environmentMap", 2);
            shader.SetInt("diffuseMap1", 3);
            shader.SetInt("blendMap", 4);

            SetupFogUniforms();
            SetLightKitUniforms();

            GeometryBase renderthis;
            foreach (BaseClass geom in resourcePool.aGeometryPool)
            {
                renderthis = (GeometryBase)geom;

                if (!renderthis.CanRender || (alphaTransparency && renderthis.isTransparent)) continue;//) { continue; }//
                if (renderthis.CulledInstanceInfos.Count == 0) continue;

                shader.SetInt("Flags", renderthis.Flags);
                shader.SetInt("ShaderOpsFlags", (int)renderthis.ShaderOpsFlags);
                shader.SetColor4("ambientScale", renderthis.ambientScale);
                shader.SetFloat("environmentScale", renderthis.environmentScale);

                SetupTextures(renderthis);
                

                renderthis.Render();
            }

            if (!alphaTransparency) return;
            // ALPHA TRANSPARENCY
            //return; // Disabled for now because of performance reasons. Optimize via compute shader perhaps?
            List<GeometryBase> transparentGeometries = new();
            foreach (BaseClass geom in resourcePool.aGeometryPool)
            {
                renderthis = (GeometryBase)geom;

                if (!renderthis.CanRender || !renderthis.isTransparent) { continue; }

                transparentGeometries.Add(renderthis);
            }

            List<InstanceDepth> depthList = new List<InstanceDepth>();

            for (int geometryIndex = 0; geometryIndex < transparentGeometries.Count; geometryIndex++)
            {
                GeometryBase geometry = transparentGeometries[geometryIndex];
                for (int instanceIndex = 0; instanceIndex < geometry.CulledInstanceInfos.Count; instanceIndex++)
                {
                    Matrix4 instanceMatrix = ConverterTools.ToOpenTK(geometry.CulledInstanceInfos[instanceIndex].matrix);
                    instanceMatrix.Transpose();
                    OpenTK.Vector3 instancePosition = (instanceMatrix * new OpenTK.Vector4(ConverterTools.ToOpenTK(geometry.GetAABBCenter()), 1)).Xyz;

                    float depth = OpenTK.Vector3.Distance(camera.GetPosition(), instancePosition);

                    depthList.Add(new InstanceDepth(geometryIndex, instanceIndex, depth));
                }
            }
            // Sort via depth
            depthList.Sort((a, b) => b.Depth.CompareTo(a.Depth));

            renderhelper.EnableBlending();

            foreach (InstanceDepth instanceDepth in depthList)
            {
                renderthis = transparentGeometries[instanceDepth.GeometryIndex];

                shader.SetInt("Flags", renderthis.Flags);
                shader.SetInt("ShaderOpsFlags", (int)renderthis.ShaderOpsFlags);
                shader.SetColor4("ambientScale", renderthis.ambientScale);
                shader.SetFloat("environmentScale", renderthis.environmentScale);

                SetupTextures(renderthis);

                renderthis.RenderInstance(instanceDepth.InstanceIndex);
            }

            renderhelper.DisableBlending();
        }

        public int ReadSelectionIndex(int x, int y)
        {
            MakeCurrent();
            DrawSelectionBuffer();

            selectionFrame.Bind();
            GL.ReadBuffer(ReadBufferMode.ColorAttachment0);

            byte[] pixels = new byte[4];
            GL.ReadPixels(x, Height - y, 1, 1, OpenTK.Graphics.OpenGL4.PixelFormat.Rgba, PixelType.UnsignedByte, pixels);
            selectionFrame.Unbind();

            int index = 0;
            for (int i = 0; i < 3; i++)
            {
                index |= pixels[i] << (i * 8);
            }


            return index - 1;
        }


        public HashSet<uint> ReadSelectionIds(Rectangle rectangle)
        {
            int x = Math.Clamp(
                rectangle.Left,
                0,
                glControl.ClientSize.Width - 1);

            int top = Math.Clamp(
                rectangle.Top,
                0,
                glControl.ClientSize.Height - 1);

            int right = Math.Clamp(
                rectangle.Right,
                0,
                glControl.ClientSize.Width);

            int bottom = Math.Clamp(
                rectangle.Bottom,
                0,
                glControl.ClientSize.Height);

            int width = right - x;
            int height = bottom - top;

            if (width <= 0 || height <= 0)
                return new HashSet<uint>();

            int requiredLength = width * height;

            byte[] _selectionPixels = new byte[4 * requiredLength];

            int openGlY =
                glControl.ClientSize.Height - bottom;

            MakeCurrent();
            DrawSelectionBuffer();

            selectionFrame.Bind();
            GL.ReadBuffer(ReadBufferMode.ColorAttachment0);

            GL.ReadPixels(
                x,
                openGlY,
                width,
                height,
                OpenTK.Graphics.OpenGL4.PixelFormat.Rgba, PixelType.UnsignedByte, _selectionPixels);

            selectionFrame.Unbind();

            var selectedIds = new HashSet<uint>();

            for (int index = 0; index < requiredLength; index++)
            {
                int id = 0;
                for (int i = 0; i < 3; i++)
                {
                    id |= _selectionPixels[i + index * 4] << (i * 8);
                }
                // Assuming zero means "nothing selected."
                if (id != 0)
                    selectedIds.Add((uint)id-1);
            }

            return selectedIds;
        }


        private void CullaGeometry(GeometryBase geom)
        {
            System.Numerics.Vector3 center = geom.GetBoundSphereCenter();
            float radius = geom.GetBoundSphereRadius();

            geom.CulledInstanceInfos.Clear();
            foreach (InstanceInfo info in geom.InstanceInfos)
            {
                System.Numerics.Vector4 worldcenter = System.Numerics.Vector4.Transform(new System.Numerics.Vector4(center, 1), info.matrix);
                float worldradius = radius * Math.Max(
                    new System.Numerics.Vector3(info.matrix.M11, info.matrix.M12, info.matrix.M13).Length(),
                    Math.Max(

                    new System.Numerics.Vector3(info.matrix.M21, info.matrix.M22, info.matrix.M23).Length(),
                    new System.Numerics.Vector3(info.matrix.M31, info.matrix.M32, info.matrix.M33).Length()));
                //geom.CulledInstanceInfos.Add(info);
                if (camera.frustum.isSphereInsideFrustum(new OpenTK.Vector3(worldcenter.X, worldcenter.Y, worldcenter.Z), worldradius))
                    geom.CulledInstanceInfos.Add(info);

            }

