            if (pauseRendering) { return; }

            DateTime now = DateTime.Now;
            TimeSpan elapsedTime = now - lastFrameTime;

            dt = (float)elapsedTime.TotalSeconds;
            lastFrameTime = now;

            MakeCurrent();

            PreRender?.Invoke(this, EventArgs.Empty);

            var stopwatch = Stopwatch.StartNew();
            HandleUserInput();
            double userinputms = stopwatch.Elapsed.TotalMilliseconds;

            //if (camera.frustum.isSphereInsideFrustum(new OpenTK.Vector3(2, 0, 0), 0)) Debug.debugWindow.AddEntry("Paint", "isinside!");


            
            GL.Clear(ClearBufferMask.ColorBufferBit | ClearBufferMask.DepthBufferBit | ClearBufferMask.StencilBufferBit);


            camera.UpdateViewProj();
            renderhelper.view = camera.GetViewMatrix();
            renderhelper.projection = camera.GetProjectionMatrix();

            stopwatch.Restart();
            // Cull anything that isn't going to be on screen and buffer (in-archive geometry only atm)
            CullAndBufferContainers();
            double cullandbufferms = stopwatch.Elapsed.TotalMilliseconds;


            /*stopwatch.Restart();
            // Draw buffer that's used for click selection
            DrawSelectionBuffer();
