            DrawSelectedContainerOutlines();
            double outlinebufferms = stopwatch.Elapsed.TotalMilliseconds;

            

            glControl.SwapBuffers();    // Display the result.


            PostRender?.Invoke(this, EventArgs.Empty);
            //drawTimer.Stop();


            /*DateTime _now = DateTime.Now;
            TimeSpan _elapsedTime = _now - lastTime;
            if(_elapsedTime.TotalSeconds > 1.0)
            {
                Debug.debugWindow.AddEntry("Draw", DebugEntryType.NORMAL, userinputms, cullandbufferms, regularbufferms, outlinebufferms);
            }*/
