                renderhelper.RenderLine(System.Numerics.Vector3.UnitX * -N + x * System.Numerics.Vector3.UnitZ, System.Numerics.Vector3.UnitX * N + x * System.Numerics.Vector3.UnitZ, Color4.Gray, 1);
