                renderhelper.RenderLine(System.Numerics.Vector3.UnitZ * -N + x * System.Numerics.Vector3.UnitX, System.Numerics.Vector3.UnitZ * N + x * System.Numerics.Vector3.UnitX, Color4.Gray, 1);
            }
        }


        private void CalculateFPS()
        {
            frameCount++;

            // Calculate the FPS every second
            DateTime now = DateTime.Now;
            TimeSpan elapsedTime = now - lastTime;

            

            if (elapsedTime.TotalSeconds >= 1.0)
            {
                // FPS calculation
                fps = frameCount / elapsedTime.TotalSeconds;

                //Application.DoEvents();
                //Debug.debugWindow.AddEntry("CalculateFPS", type:DebugEntryType.NORMAL, dthistory.ToArray());
                
                // Reset for the next second
                frameCount = 0;
                lastTime = now;
            }
        }
    }

    public struct InstanceDepth
    {
        public int GeometryIndex;
        public int InstanceIndex;
        public float Depth;

        public InstanceDepth(int geometryIndex, int instanceIndex, float depth)
        {
            GeometryIndex = geometryIndex;
            InstanceIndex = instanceIndex;
            Depth = depth;
        }
    }
}
